import 'package:cloud_firestore/cloud_firestore.dart';
DateTime? _wDate(dynamic v)=>v is Timestamp?v.toDate():v is DateTime?v:null; Timestamp? _wStamp(DateTime? v)=>v==null?null:Timestamp.fromDate(v);
class WomenDoctor {final String id,name,specialty,photoUrl,address,phone;final double rating;final int reviewCount,experienceYears;final bool isVerified,isAvailable;final DateTime? createdAt,updatedAt;const WomenDoctor({required this.id,required this.name,required this.specialty,this.photoUrl='',this.rating=0,this.reviewCount=0,this.experienceYears=0,this.address='',this.phone='',this.isVerified=false,this.isAvailable=true,this.createdAt,this.updatedAt});factory WomenDoctor.fromFirestore(String id,Map<String,dynamic>d)=>WomenDoctor(id:id,name:'${d['name']??''}',specialty:'${d['specialty']??'نساء'}',photoUrl:'${d['photoUrl']??''}',rating:(d['rating']as num?)?.toDouble()??0,reviewCount:(d['reviewCount']as num?)?.toInt()??0,experienceYears:(d['experienceYears']as num?)?.toInt()??0,address:'${d['address']??''}',phone:'${d['phone']??''}',isVerified:d['isVerified']==true,isAvailable:d['isAvailable']!=false,createdAt:_wDate(d['createdAt']),updatedAt:_wDate(d['updatedAt']));Map<String,dynamic>toFirestore()=>{'name':name,'specialty':specialty,'photoUrl':photoUrl,'rating':rating,'reviewCount':reviewCount,'experienceYears':experienceYears,'address':address,'phone':phone,'isVerified':isVerified,'isAvailable':isAvailable,'createdAt':_wStamp(createdAt),'updatedAt':_wStamp(updatedAt)};}
class WomenClinic {final String id,name,type,address,phone;final double rating;final bool isOpen;final GeoPoint? location;const WomenClinic({required this.id,required this.name,this.type='نساء',this.address='',this.phone='',this.rating=0,this.isOpen=true,this.location});factory WomenClinic.fromFirestore(String id,Map<String,dynamic>d)=>WomenClinic(id:id,name:'${d['name']??''}',type:'${d['type']??'نساء'}',address:'${d['address']??''}',phone:'${d['phone']??''}',rating:(d['rating']as num?)?.toDouble()??0,isOpen:d['isOpen']!=false,location:d['location']is GeoPoint?d['location']as GeoPoint:null);Map<String,dynamic>toFirestore()=>{'name':name,'type':type,'address':address,'phone':phone,'rating':rating,'isOpen':isOpen,'location':location};}
class WomenTip {final String id,title,body,category;final bool isPublished;final DateTime? createdAt;const WomenTip({required this.id,required this.title,required this.body,this.category='دورة',this.isPublished=true,this.createdAt});factory WomenTip.fromFirestore(String id,Map<String,dynamic>d)=>WomenTip(id:id,title:'${d['title']??''}',body:'${d['body']??''}',category:'${d['category']??'دورة'}',isPublished:d['isPublished']!=false,createdAt:_wDate(d['createdAt']));Map<String,dynamic>toFirestore()=>{'title':title,'body':body,'category':category,'isPublished':isPublished,'createdAt':_wStamp(createdAt)};}
class WomenHospital {final String id,name,address,phone;final bool emergency,isOpen;final GeoPoint? location;const WomenHospital({required this.id,required this.name,this.address='',this.phone='',this.emergency=false,this.isOpen=true,this.location});factory WomenHospital.fromFirestore(String id,Map<String,dynamic>d)=>WomenHospital(id:id,name:'${d['name']??''}',address:'${d['address']??''}',phone:'${d['phone']??''}',emergency:d['emergency']==true,isOpen:d['isOpen']!=false,location:d['location']is GeoPoint?d['location']as GeoPoint:null);Map<String,dynamic>toFirestore()=>{'name':name,'address':address,'phone':phone,'emergency':emergency,'isOpen':isOpen,'location':location};}
class WomenConsultation {final String id,userId,doctorId,question,status,answer;final DateTime? createdAt,answeredAt;const WomenConsultation({required this.id,required this.userId,this.doctorId='',required this.question,this.status='pending',this.answer='',this.createdAt,this.answeredAt});factory WomenConsultation.fromFirestore(String id,Map<String,dynamic>d)=>WomenConsultation(id:id,userId:'${d['userId']??''}',doctorId:'${d['doctorId']??''}',question:'${d['question']??''}',status:'${d['status']??'pending'}',answer:'${d['answer']??''}',createdAt:_wDate(d['createdAt']),answeredAt:_wDate(d['answeredAt']));Map<String,dynamic>toFirestore()=>{'userId':userId,'doctorId':doctorId,'question':question,'status':status,'answer':answer,'createdAt':_wStamp(createdAt),'answeredAt':_wStamp(answeredAt)};}
